import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import FileUploader from './FileUploader';

const validFileMock = {
  file: {
    name: 'validFileMock',
    size: 350000,
  },
  valid: true,
  id: 'validFileMock',
  errors: [],
};

describe('FileUploader', () => {
  window.URL.createObjectURL = jest.fn();
  it('should render with the message', () => {
    const { container } = render(<FileUploader message="Upload your files" />);
    const section = container.querySelector('section');
    fireEvent.mouseEnter(section);
    fireEvent.mouseLeave(section);
    expect(screen.getByText('Upload your files')).toBeInTheDocument();
  });

  it('should render the error component, if there is a error prop', () => {
    render(
      <FileUploader message="Upload your files" type="file" error={{ message: 'Error Message' }} />
    );
    expect(screen.getByText('Error Message')).toBeInTheDocument();
  });

  it('should render the error component with an action button and call the callback function when clicked', () => {
    const callback = jest.fn();
    render(
      <FileUploader
        message="Upload your files"
        error={{ message: 'Error Message', action: { name: 'Button', action: callback } }}
      />
    );
    expect(screen.getByText('Button')).toBeInTheDocument();
    fireEvent.click(screen.getByText('Button'));
    expect(callback).toHaveBeenCalled();
  });

  it('should render the description of the selected document', () => {
    render(<FileUploader type="document" message="Upload your files" value={[validFileMock]} />);
    expect(screen.getByText('validFileMock')).toBeInTheDocument();
    expect(screen.getByText('350kb')).toBeInTheDocument();
  });

  it('should render the delete and edit buttons when there is a document or file selected', async () => {
    const user = userEvent.setup();
    const onCleanMock = jest.fn();
    const { container } = render(
      <FileUploader
        type="file"
        message="Upload your files"
        value={[validFileMock]}
        onClean={onCleanMock}
      />
    );
    const deleteButton = container.querySelector('[aria-label="Delete and clear"]');
    expect(deleteButton).toBeInTheDocument();
    expect(container.querySelector('[aria-label="Edit"]')).toBeInTheDocument();

    await user.click(deleteButton);
    expect(onCleanMock).toHaveBeenCalled();
  });

  it('should render the delete and edit buttons when there is a image selected', async () => {
    const user = userEvent.setup();
    const onCleanMock = jest.fn();
    const { container } = render(
      <FileUploader message="Upload your files" value={[validFileMock]} onClean={onCleanMock} />
    );
    const deleteButton = container.querySelector('[aria-label="Delete and clear"]');
    expect(deleteButton).toBeInTheDocument();
    expect(container.querySelector('[aria-label="Edit"]')).toBeInTheDocument();

    await user.click(deleteButton);
    expect(onCleanMock).toHaveBeenCalled();
  });

  it('should call the onDrop from props', async () => {
    const onDropMock = jest.fn();
    const user = userEvent.setup();
    const { rerender, container } = render(
      <FileUploader type="document" message="Upload your files" value={[]} onDrop={onDropMock} />
    );

    const fileDropzone = container.querySelector('[type="file"]');

    await user.upload(fileDropzone, {
      name: 'validFileMock',
      size: 350000,
    });

    expect(onDropMock).toHaveBeenCalled();
    rerender(<FileUploader type="document" message="Upload your files" onDrop={onDropMock} />);
    expect(screen.getByText('validFileMock')).toBeInTheDocument();
  });

  it('should render with initial image url', async () => {
    render(
      <FileUploader
        type="image"
        imageUrl="https://one-uat.bees-platform.dev/mf/admin-portal-main-mfe/69578b051631db0e07b7.svg"
        alt="Bees logo"
        message="Upload your files"
      />
    );

    expect(
      screen.getByRole('img', {
        name: 'Bees logo',
      })
    ).toBeInTheDocument();
    expect(screen.queryByText('Upload your files')).not.toBeInTheDocument();
  });
});
